def set_mode_circle():
    global mode, rect_selected, rect, polygon_points, point_ids, polygon_id, moving_point, dragging,dragging_handle,center_x,center_y,radius,circle_id
    mode = "circle"
    rect_selected = False
    canvas.delete("mark","line","text","rect","polygon","circle")
